export type ReposTestPushWebhookError = BasicError;

export interface ReposTestPushWebhookParams {
  owner: string;
  repo: string;
  hookId: number;
}

/**
 * This will trigger the hook with the latest push to the current repository if the hook is subscribed to `push` events. If the hook is not subscribed to `push` events, the server will respond with 204 but no test POST will be generated. > [!NOTE] > Previously `/repos/:owner/:repo/hooks/:hook_id/test`
 *
 * @param owner - The account owner of the repository. The name is not case
 *   sensitive.
 * @param repo - The name of the repository without the `.git` extension. The
 *   name is not case sensitive.
 * @param hookId - The unique identifier of the hook. You can find this value in
 *   the `X-GitHub-Hook-ID` header of a webhook delivery.
 */
export async function reposTestPushWebhook(
  config: ClientConfig,
  { owner, repo, hookId }: ReposTestPushWebhookParams,
  requestOptions?: RequestOptions,
): Promise<void> {
  const _resp = await sdkRequest<void>({
    method: "POST",
    path: `/repos/${encodePathSegment(owner)}/${encodePathSegment(repo)}/hooks/${encodePathSegment(hookId)}/tests`,
    operationId: "reposTestPushWebhook",
    errors: { "404": "BasicError" },
    responseDecoder: "empty",
    ...requestOptions,
    config,
  });
  void _resp.data;
  return;
}
